<h1>Academics</h1><p class="muted">Published examination results and report cards.</p>
<div class="card" style="margin-top:var(--space-4)"><div class="card-body"><h3>Report Cards</h3><table class="table"><thead><tr><th>Examination</th><th>Term</th><th>Published</th></tr></thead><tbody><?php foreach($report_cards as $card): ?><tr><td><?= e($card['examination_name']) ?></td><td><?= e($card['term_name']) ?></td><td><?= e((string)$card['published_at']) ?></td></tr><?php endforeach; if(!$report_cards): ?><tr><td colspan="3">No published report cards yet.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="card" style="margin-top:var(--space-4)"><div class="card-body"><h3>Results</h3><table class="table"><thead><tr><th>Subject</th><th>Examination</th><th>Percentage</th><th>Grade</th><th>Points</th><th>Remark</th></tr></thead><tbody><?php foreach($results as $r): ?><tr><td><?= e($r['subject_name']) ?></td><td><?= e($r['examination_name']) ?></td><td><?= e((string)$r['percentage']) ?></td><td><?= e((string)$r['grade']) ?></td><td><?= e((string)$r['points']) ?></td><td><?= e((string)$r['remark']) ?></td></tr><?php endforeach; if(!$results): ?><tr><td colspan="6">No published results yet.</td></tr><?php endif; ?></tbody></table></div></div>
